def minPath(grid, k):
    n = len(grid)
    r1, c1 = -1, -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                r1, c1 = r, c
                break
        if r1 != -1:
            break

    min_neighbor = float('inf')
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r1 + dr, c1 + dc
        if 0 <= nr < n and 0 <= nc < n:
            min_neighbor = min(min_neighbor, grid[nr][nc])

    return [1 if i % 2 == 0 else min_neighbor for i in range(k)]

